% exercise2.m
fs = 200;
T = 1;
t = 0:1/fs:T-1/fs;

x = 0.8*sin(2*pi*15*t) + 0.4*sin(2*pi*40*t);

% Single-sided amplitude spectrum
N = length(x);
Y = fft(x);

P2 = abs(Y/N);
P1 = P2(1:N/2+1);
P1(2:end-1) = 2*P1(2:end-1);

f = fs*(0:N/2)/N;

% Print the peaks and the bin spacing
df = fs/N;
fprintf('N = %d, bin spacing = %.4f Hz\n', N, df); %[output:7f966f64]
idx = find(P1 > 0.1);
for i = 1:length(idx) %[output:group:3fc462bc]
    fprintf('Peak at f = %.2f Hz, amplitude = %.4f\n', f(idx(i)), P1(idx(i))); %[output:082e60d0]
end %[output:group:3fc462bc]

% Plots
figure %[output:5bcdae86]
subplot(2, 1, 1) %[output:5bcdae86]
plot(t, x) %[output:5bcdae86]
grid on %[output:5bcdae86]
xlabel('Time (s)') %[output:5bcdae86]
ylabel('Amplitude') %[output:5bcdae86]
title('Signal in the time domain') %[output:5bcdae86]

subplot(2, 1, 2) %[output:5bcdae86]
plot(f, P1) %[output:5bcdae86]
grid on %[output:5bcdae86]
xlabel('Frequency (Hz)') %[output:5bcdae86]
ylabel('Amplitude') %[output:5bcdae86]
title('Single-sided amplitude spectrum') %[output:5bcdae86]

exportgraphics(gcf, 'two-frequency-spectrum.png', 'Resolution', 300) %[output:5bcdae86]

